def split_fraction(fraction):
    numerator, denominator = fraction.split('/')
    return int(numerator), int(denominator)

def simplify(x, n):
    numerator_x, denominator_x = split_fraction(x)
    numerator_n, denominator_n = split_fraction(n)
    product_numerator = numerator_x * numerator_n
    product_denominator = denominator_x * denominator_n
    common_divisor = gcd(product_numerator, product_denominator)
    simplified_numerator = product_numerator // common_divisor
    simplified_denominator = product_denominator // common_divisor
    return simplified_denominator == 1

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

